457	LiaStarExtension::Subsolver& LiaStarExtension::getSubsolver(Node lambda)
458	{
459	  // Return the persistent incremental subsolver for `lambda`, creating and
460	  // seeding it on first use. It is used by the lazy strategy to enumerate the
461	  // convex cells of the predicate's satisfying region.
462	  auto it = d_subsolvers.find(lambda);
463	  if (it != d_subsolvers.end())
464	  {
465	    return it->second;
466	  }
467	  Subsolver& sub = d_subsolvers[lambda];
468	
469	  Options subOptions;
470	  // we read the model below to construct the disjunct.
471	  subOptions.write_smt().produceModels = true;
472	  sub.engine = std::make_unique<SolverEngine>(d_nm, &subOptions);
473	  sub.engine->setIsInternalSubsolver();
474	  LogicInfo info("QF_LIA");
475	  sub.engine->setLogic(info);
476	  sub.engine->setOption("incremental", "true");
477	
478	  // The base assertion is the membership predicate (with ites and negations
479	  // eliminated) conjoined with the non-negativity of the lambda's variables.
480	  Node base = LiaStarUtils::removeItesAndNots(lambda[1], &d_env);
481	  std::vector<Node> conjuncts{base};
482	  for (Node var : lambda[0])
483	  {
484	    conjuncts.push_back(d_nm->mkNode(Kind::GEQ, var, d_zero));
485	  }
486	  base =
487	      conjuncts.size() == 1 ? conjuncts[0] : d_nm->mkNode(Kind::AND, conjuncts);
488	
489	  // The lambda's bound variables appear free in `base`. A formula with free
490	  // (bound) variables cannot be asserted to a subsolver, so we replace them
491	  // with fresh free constants and remember the mapping so the disjunct built
492	  // from the model can be substituted back into bound-variable space.
493	  for (Node var : lambda[0])
494	  {
495	    if (var.getKind() == Kind::BOUND_VARIABLE)
496	    {
497	      sub.from.push_back(var);
498	      sub.to.push_back(d_nm->mkDummySkolem("liastar", var.getType()));
499	    }
500	  }
501	  if (!sub.from.empty())
502	  {
503	    base = base.substitute(
504	        sub.from.begin(), sub.from.end(), sub.to.begin(), sub.to.end());
505	  }
506	  sub.base = base;
507	  sub.engine->assertFormula(base);
508	  return sub;
509	}
